def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        r = (props.get(element) or {}).get('covalent_radius_A')
        if fraction is not None and fraction > 0 and r is not None and r > 0:
            total += fraction * r * r * r
            weight += fraction
    return 4.0 * pi * total / (3.0 * weight * v) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    nearest = [inf] * n
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    total = 0.0
    weight = 0.0
    for i in range(n):
        w = sites[i].get('occupancy')
        w = 1.0 if w is None else max(0.0, w)
        if nearest[i] < inf:
            total += w * nearest[i]
            weight += w
    return total / weight if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    nearest = [inf] * n
    occupancy = []
    for site in sites:
        w = site.get('occupancy')
        occupancy.append(1.0 if w is None else max(0.0, w))
    bonds = s.get('neighbors') or []
    for bond in bonds:
        i = bond.get('i', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    coordination = [0.0] * n
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.3 * nearest[i]:
            coordination[i] += occupancy[j]
    weight = sum(occupancy)
    if weight <= 0:
        return 0.0
    mean = sum(occupancy[i] * coordination[i] for i in range(n)) / weight
    if mean <= 0:
        return 0.0
    variance = sum(occupancy[i] * (coordination[i] - mean) ** 2 for i in range(n)) / weight
    return sqrt(max(0.0, variance)) / mean

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    en = []
    occupancy = []
    for site in sites:
        en.append((props.get(site.get('element')) or {}).get('eneg'))
        w = site.get('occupancy')
        occupancy.append(1.0 if w is None else max(0.0, w))
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for bond in bonds:
        i = bond.get('i', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    total = 0.0
    weight = 0.0
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.3 * nearest[i]:
            if en[i] is not None and en[j] is not None:
                w = occupancy[i] * occupancy[j]
                total += w * (1.0 - exp(-0.25 * (en[i] - en[j]) ** 2))
                weight += w
    return total / weight if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    en = []
    occupancy = []
    for site in sites:
        en.append((props.get(site.get('element')) or {}).get('eneg'))
        w = site.get('occupancy')
        occupancy.append(1.0 if w is None else max(0.0, w))
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for bond in bonds:
        i = bond.get('i', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    contrast = [0.0] * n
    counts = [0.0] * n
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.3 * nearest[i]:
            if en[i] is not None and en[j] is not None:
                contrast[i] += occupancy[j] * (en[j] - en[i])
                counts[i] += occupancy[j]
    total = 0.0
    weight = 0.0
    for i in range(n):
        if counts[i] > 0:
            total += occupancy[i] * (contrast[i] / counts[i]) ** 2
            weight += occupancy[i]
    return sqrt(total / weight) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    values = [x for x in (s.get('composition') or {}).values() if x is not None and x > 0]
    total = sum(values)
    if total <= 0:
        return 0.0
    return -sum((x / total) * log(x / total) for x in values)

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        p = props.get(element) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if fraction is not None and fraction > 0 and ionization is not None and affinity is not None:
            total += fraction * 0.5 * (ionization - affinity)
            weight += fraction
    return total / weight if weight > 0 else 0.0

