def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    chi = []
    hardness = []
    occupancy = []
    for site in sites:
        p = props.get(site.get('element')) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is not None and affinity is not None and ionization > affinity:
            chi.append(0.5 * (ionization + affinity))
            hardness.append(0.5 * (ionization - affinity))
        else:
            chi.append(None)
            hardness.append(None)
        w = site.get('occupancy')
        occupancy.append(1.0 if w is None else max(0.0, w))
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for bond in bonds:
        i = bond.get('i', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d < nearest[i]:
            nearest[i] = d
    total = 0.0
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.3 * nearest[i]:
            if chi[i] is not None and chi[j] is not None:
                stabilization = (chi[i] - chi[j]) ** 2 / (2.0 * (hardness[i] + hardness[j]))
                total += occupancy[i] * occupancy[j] * stabilization
    weight = sum(occupancy)
    return 0.5 * total / weight if weight > 0 else 0.0

def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        valence = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and fraction > 0 and valence is not None:
            total += fraction * valence
            weight += fraction
    return total / (weight * v) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    lattice = s.get('lattice') or {}
    lengths = lattice.get('lengths_A')
    if lengths is None:
        lengths = [lattice.get('a_A'), lattice.get('b_A'), lattice.get('c_A')]
    values = [x for x in lengths if x is not None and x > 0]
    if len(values) != 3:
        return 0.0
    return log(max(values) / min(values))
